  Hypothesis CBL : DT + 4 + 8192 <= lo.
  Hypothesis DJ1 : DT + 4 + 8192 <= DST \/ DST + dcap <= DT.
  Hypothesis DJ3 : DST + dcap <= SS \/ SS + n <= DST.
  Hypothesis LOS : lo <= SP - 4096.
  Hypothesis SP16 : SP mod 16 = 0.
  Hypothesis SP47 : SP <= 2^47.

  Notation DW := [(SP - 4096, SP); (DST, DST + dcap)].
  Notation POST := (huf_dec_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc DST dcap lo m0).
  Notation FRS := [C8 s11; C8 s10; C8 s9; C8 s8; C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra].

  (* [comment removed for export] *)
  Definition Y4M (mm : fmem) (sps ws : list word) : Prop :=
    (exists buf, u8arr psegs mm DST (map (Z_to_bv 8) buf) /\ zlen buf = dcap)
    /\ bytes_at psegs mm SS (map (Z_to_bv 8) src)
    /\ bytes_at psegs mm (DT + 4) cbs
    /\ stk psegs mm lo (SP + -416)
    /\ (exists j0, rw_cells psegs mm (SP + -416) [CB 72 j0])
    /\ u64arr psegs mm (SP + -344) sps /\ length sps = 11%nat
    /\ u64arr psegs mm (SP + -256) ws /\ length ws = 19%nat
    /\ rw_cells psegs mm (SP + -104) FRS
    /\ mem_inv psegs mm /\ munch DW m0 mm /\ wmono psegs m0 mm.

  (* [comment removed for export] *)
  Definition SPS : list word :=
    [Z_to_bv 64 n; Z_to_bv 64 SS; Z_to_bv 64 DT; Z_to_bv 64 DST; Z_to_bv 64 dcap; Z_to_bv 64 (DST + dcap);
     Z_to_bv 64 2635249153387078803; Z_to_bv 64 (DST + dcap); Z_to_bv 64 SS; Z_to_bv 64 (DST + 2 * seg); Z_to_bv 64 (DST + seg)].

  (* [comment removed for export] *)
  Notation HO pc mm b0 b1 b2 b3 IP0 IP1 IP2 IP3 OP0 OP1 OP2 OP3 x6 x9 x13 x14 x19 x20 x21 x24 x29 x30 x31 :=
    (MS (mkR b3 (Z_to_bv 64 (SP + -416)) gp tp (Z_to_bv 64 IP0) x6 (Z_to_bv 64 OP2) (Z_to_bv 64 (DT + 4)) x9 (Z_to_bv 64 (DT + 4))
             b0 b1 x13 x14 (Z_to_bv 64 IP3) (Z_to_bv 64 IP2) (Z_to_bv 64 IP1) b2 x19 x20 x21
             (Z_to_bv 64 14757395258967641293) (Z_to_bv 64 0x10380) x24
             (Z_to_bv 64 OP0) (Z_to_bv 64 OP1) (Z_to_bv 64 OP3) (Z_to_bv 64 (DST + 3 * seg)) x29 x30 x31)
        F (Z_to_bv 64 pc) fc None mm (seg_rom psegs)).

  Lemma y4_tabfact : forall mm, bytes_at psegs mm (DT + 4) cbs -> KXTac.ztab_fact psegs mm (DT + 4) 8192 4 [(2, 0, 11); (3, 1, 2)].
Proof using TOK ECB.
