  (* [comment removed for export] *)
  Lemma y4_inner : forall (r : nat) mm ws (b0 b1 b2 b3 : word) IP0 IP1 IP2 IP3 OP0 OP1 OP2 OP3 OL
                          (x6 x9 x13 x19 x20 x21 x29 x30 x31 : word),
    Y4M mm SPS ws -> (1 <= r)%nat -> OL <= OP3 + 5 * Z.of_nat r -> OP3 < OL -> OL < 2^47 ->
    OP0 + 10 * Z.of_nat r <= DST + seg -> OP1 + 10 * Z.of_nat r <= DST + 2 * seg ->
    OP2 + 10 * Z.of_nat r <= DST + 3 * seg -> OP3 + 10 * Z.of_nat r <= DST + dcap ->
    DST <= OP0 -> DST <= OP1 -> DST <= OP2 -> DST <= OP3 ->
    SS + 7 * Z.of_nat r <= IP0 -> IP0 + 8 <= SS + n -> SS + 7 * Z.of_nat r <= IP1 -> IP1 + 8 <= SS + n ->
    SS + 7 * Z.of_nat r <= IP2 -> IP2 + 8 <= SS + n -> SS + 7 * Z.of_nat r <= IP3 -> IP3 + 8 <= SS + n ->
    (forall mm' (b0' b1' b2' b3' : word) IP0' IP1' IP2' IP3' OP0' OP1' OP2' OP3' (x6' x9' x13' x19' x20' x21' x29' x30' x31' : word),
       Y4M mm' SPS ws ->
       SS <= IP0' -> IP0' + 8 <= SS + n -> SS <= IP1' -> IP1' + 8 <= SS + n ->
       SS <= IP2' -> IP2' + 8 <= SS + n -> SS <= IP3' -> IP3' + 8 <= SS + n ->
       DST <= OP0' <= DST + seg -> DST <= OP1' <= DST + 2 * seg -> DST <= OP2' <= DST + 3 * seg ->
       OL <= OP3' <= DST + dcap ->
       evt psegs POST (HO 0x15384 mm' b0' b1' b2' b3' IP0' IP1' IP2' IP3' OP0' OP1' OP2' OP3' x6' x9' x13' (Z_to_bv 64 0x104d0)
                          x19' x20' x21' (Z_to_bv 64 OL) x29' x30' x31')) ->
    evt psegs POST (HO 0x15460 mm b0 b1 b2 b3 IP0 IP1 IP2 IP3 OP0 OP1 OP2 OP3 x6 x9 x13 (Z_to_bv 64 0x104d0)
                       x19 x20 x21 (Z_to_bv 64 OL) x29 x30 x31).
